// DO NOT EDIT — generated scaffold for JUM-958
// Fetches the ONDO Global Markets tokenlist and writes a typed TS denylist module.
import { writeFileSync, mkdirSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const TOKENLIST_URL =
  'https://raw.githubusercontent.com/ondoprotocol/ondo-global-markets-token-list/main/tokenlist.json';
const OUT_FILE = join(__dirname, 'src/config/generated/ondoDenylist.ts');

async function main() {
  const response = await fetch(TOKENLIST_URL);
  if (!response.ok) {
    throw new Error(`Failed to fetch tokenlist: ${response.status} ${response.statusText}`);
  }

  const tokenList = await response.json();

  const deny = tokenList.tokens
    .map((token) => ({ address: token.address.toLowerCase(), chainId: token.chainId }))
    .sort((a, b) => a.chainId - b.chainId || a.address.localeCompare(b.address));

  const lines = deny.map(
    ({ address, chainId }) => `  { address: '${address}', chainId: ${chainId} },`,
  );

  const content = [
    `// DO NOT EDIT — generated by gen-ondo-denylist.mjs (JUM-958)`,
    `// Source: ${TOKENLIST_URL}`,
    `import type { BaseToken } from '@lifi/sdk';`,
    ``,
    `export const ondoDenylist: Array<Pick<BaseToken, 'address' | 'chainId'>> = [`,
    ...lines,
    `];`,
    ``,
  ].join('\n');

  mkdirSync(dirname(OUT_FILE), { recursive: true });
  writeFileSync(OUT_FILE, content, 'utf8');
  console.log(`Written ${deny.length} entries to ${OUT_FILE}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
